import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Korisnik {
  ime: string;
  prezime: string;
  email: string;
  lozinka: string;
  rola?: string; // optional, backend postavlja CITIZEN po defaultu
}

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  private baseUrl = 'http://localhost:8080/api/auth';

  constructor(private http: HttpClient) { }

  // Registracija korisnika
  register(korisnik: Korisnik): Observable<any> {
    return this.http.post(`${this.baseUrl}/register`, korisnik);
  }

  // Login korisnika
  login(email: string, lozinka: string): Observable<any> {
    return this.http.post(`${this.baseUrl}/login`, { email, lozinka });
  }
}
